const root = $json || {};

const body = root.body && typeof root.body === "object" ? root.body : root;
const query = root.query && typeof root.query === "object" ? root.query : {};
const params = root.params && typeof root.params === "object" ? root.params : {};

const action =
  body.action ??
  query.action ??
  params.action ??
  "analyzeDeal";

const dealId =
  body.dealId ??
  query.dealId ??
  params.dealId ??
  null;

const hubspotUrl =
  body.hubspotUrl ??
  query.hubspotUrl ??
  params.hubspotUrl ??
  null;

const mode =
  body.mode ??
  query.mode ??
  params.mode ??
  "full";

const contactId =
  body.contactId ??
  query.contactId ??
  params.contactId ??
  null;

const companyId =
  body.companyId ??
  query.companyId ??
  params.companyId ??
  null;

// --- helpers ---

function parseHubSpotUrl(url) {
  if (!url || typeof url !== "string") return { objectType: null, objectId: null };

  // match /record/0-3/123456 or /record/0-2/123456 etc.
  const match = url.match(/\/record\/(0-\d)\/(\d+)/);
  if (!match) return { objectType: null, objectId: null };

  const objectCode = match[1];
  const objectId = match[2];

  let objectType = null;
  if (objectCode === "0-3") objectType = "deal";
  if (objectCode === "0-2") objectType = "company";
  if (objectCode === "0-1") objectType = "contact";

  return { objectType, objectId };
}

function inferObjectTypeFromAction(actionValue) {
  const a = String(actionValue || "").toLowerCase();

  if (a === "analyzedeal" || a === "dealstrategy") return "deal";
  if (a === "accountstrategy") return "company";
  if (a === "contactbrief") return "contact";

  return null;
}

// --- object resolution priority ---
// 1. explicit ids
// 2. hubspot url
// 3. action fallback

let objectType = null;
let objectId = null;

if (dealId) {
  objectType = "deal";
  objectId = String(dealId);
} else if (companyId) {
  objectType = "company";
  objectId = String(companyId);
} else if (contactId) {
  objectType = "contact";
  objectId = String(contactId);
} else {
  const parsed = parseHubSpotUrl(hubspotUrl);
  objectType = parsed.objectType;
  objectId = parsed.objectId;
}

if (!objectType) {
  objectType = inferObjectTypeFromAction(action);
}

return [{
  json: {
    action: String(action),
    mode: mode ? String(mode).toLowerCase() : "full",

    dealId: dealId ? String(dealId) : null,
    companyId: companyId ? String(companyId) : null,
    contactId: contactId ? String(contactId) : null,

    hubspotUrl: hubspotUrl ? String(hubspotUrl) : null,

    objectType,
    objectId: objectId ? String(objectId) : null,

    raw_body: body
  }
}];

const previous = $('Code_Build_Email_Search_Body').first().json;
const response = $json || {};
const emails = response.results || [];

function cleanText(text) {
  if (!text) return "";

  let t = String(text);

  // remove html tags
  t = t.replace(/<[^>]*>/g, " ");

  // normalize line breaks and spaces
  t = t.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  t = t.replace(/\n{3,}/g, "\n\n");
  t = t.replace(/\s+/g, " ");

  // remove common disclaimers / signatures / HubSpot noise
  t = t.replace(/This email and any attachments may contain confidential information.*$/i, "");
  t = t.replace(/Ce message et toutes ses pièces jointes peuvent contenir des informations confidentielles.*$/i, "");
  t = t.replace(/Powered by HubSpot.*$/i, "");
  t = t.replace(/Is this email not relevant to you\?.*$/i, "");
  t = t.replace(/Sent from my iPhone/gi, "");
  t = t.replace(/Envoyé de mon iPhone/gi, "");

  // redact credentials / passwords
  t = t.replace(/(\bpassword\b|\bpw\b|\bpass\b)\s*[:=]\s*[^\s,;]+/gi, "$1: [REDACTED]");
  t = t.replace(/(\blogin\b|\busername\b)\s*[:=]\s*[^\s,;]+/gi, "$1: [REDACTED]");

  // redact obvious URLs if you want lighter context
  // t = t.replace(/https?:\/\/\S+/gi, "[LINK]");

  return t.trim().slice(0, 1800);
}

function normalizeList(value) {
  if (!value) return [];
  return String(value)
    .split(/[;,]/)
    .map(v => v.trim())
    .filter(Boolean);
}

function inferDirection(rawDirection, fromEmail) {
  const d = String(rawDirection || "").toLowerCase();
  const from = String(fromEmail || "").toLowerCase();

  if (d.includes("incoming") || d.includes("inbound")) return "inbound";
  if (d.includes("outgoing") || d.includes("outbound")) return "outbound";

  // HubSpot often uses plain "EMAIL"
  if (d === "email") {
    if (from.endsWith("@magrid.education")) return "outbound";
    return "inbound";
  }

  // fallback based on sender domain
  if (from.endsWith("@magrid.education")) return "outbound";
  return "inbound";
}

const normalizedEmails = emails
  .map((e) => {
    const p = e.properties || {};
    const from = p.hs_email_from_email || "";
    const normalizedDirection = inferDirection(p.hs_email_direction, from);

    return {
      id: e.id || null,
      date: p.hs_timestamp || null,
      subject: p.hs_email_subject || "",
      direction: normalizedDirection,
      raw_direction: p.hs_email_direction || "",
      from,
      to: normalizeList(p.hs_email_to_email),
      cc: normalizeList(p.hs_email_cc_email),
      body_cleaned: cleanText(p.hs_email_text || "")
    };
  })
  .filter((e) => (e.subject && e.subject.trim()) || (e.body_cleaned && e.body_cleaned.trim().length > 20));

const inboundEmails = normalizedEmails.filter((e) => e.direction === "inbound");
const outboundEmails = normalizedEmails.filter((e) => e.direction === "outbound");

return [
  {
    json: {
      ...previous,
      email_context: {
        email_count_returned: normalizedEmails.length,
        last_inbound_at: inboundEmails[0]?.date || null,
        last_outbound_at: outboundEmails[0]?.date || null,
        last_thread_at: normalizedEmails[0]?.date || null,
        emails: normalizedEmails.slice(0, 8)
      }
    }
  }
];

const objectType = $json.objectType;
const objectId = $json.objectId;

if (!objectType || !objectId) {
  return [{
    json: {
      ...$json,
      emailSearchReady: false,
      emailSearchReason: "Missing objectType or objectId",
      emailSearchBody: {}
    }
  }];
}

let associationProperty;

switch (objectType) {
  case "deal":
    associationProperty = "associations.deal";
    break;
  case "company":
    associationProperty = "associations.company";
    break;
  case "contact":
    associationProperty = "associations.contact";
    break;
  default:
    return [{
      json: {
        ...$json,
        emailSearchReady: false,
        emailSearchReason: `Unsupported objectType: ${objectType}`,
        emailSearchBody: {}
      }
    }];
}

const emailSearchBody = {
  filterGroups: [
    {
      filters: [
        {
          propertyName: associationProperty,
          operator: "EQ",
          value: String(objectId)
        }
      ]
    }
  ],
  properties: [
    "hs_timestamp",
    "hs_email_subject",
    "hs_email_text",
    "hs_email_direction",
    "hs_email_from_email",
    "hs_email_to_email",
    "hs_email_cc_email"
  ],
  sorts: [
    {
      propertyName: "hs_timestamp",
      direction: "DESCENDING"
    }
  ],
  limit: 8
};

return [{
  json: {
    ...$json,
    emailSearchReady: true,
    emailSearchReason: null,
    emailSearchBody
  }
}];
